parameters.jsCode:
const interview = $json || {};
const feedback = $('Save Feedback to DB').first().json || {};
const webhookBody = $('Webhook: Receive Feedback').first().json.body || {};

const raw = String((feedback.recommendation ?? webhookBody.recommendation ?? '')).trim().toLowerCase();
let decision = 'ON_HOLD';
if (['accept', 'strong_yes', 'yes', 'hire', 'selected'].includes(raw)) decision = 'ACCEPT';
else if (['reject', 'strong_no', 'no', 'decline', 'rejected'].includes(raw)) decision = 'REJECT';

return [{
  json: {
    decision,
    interview_id: interview.id ?? feedback.interview_id ?? webhookBody.interview_id ?? null,
    candidate_email: interview.candidate_email ?? webhookBody.candidate_email ?? '',
    candidate_name: interview.candidate_name ?? webhookBody.candidate_name ?? 'Candidate',
    round_label: interview.round_label ?? webhookBody.round_label ?? 'Interview',
    round_number: interview.round_number ?? 1,
    job_title: interview.job_title ?? webhookBody.job_title ?? webhookBody.position ?? webhookBody.role ?? '',
    technical_score: feedback.technical_score ?? webhookBody.technical_score ?? null,
    communication_score: feedback.communication_score ?? webhookBody.communication_score ?? null,
    cultural_fit_score: feedback.cultural_fit_score ?? webhookBody.cultural_fit_score ?? null,
    overall_rating: feedback.overall_rating ?? webhookBody.overall_rating ?? null,
    recommendation: feedback.recommendation ?? webhookBody.recommendation ?? '',
    comments: feedback.comments ?? webhookBody.comments ?? ''
  }
}];

